 static void TransferSentinel(Material filmic,Material encoder)
 {
  var input=new Texture2D(4,1,TextureFormat.RGBAFloat,false,true);var middle=new RenderTexture(4,1,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);var output=new RenderTexture(4,1,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);middle.Create();output.Create();var old=RenderTexture.active;bool oldWrite=GL.sRGBWrite;Texture2D pixels=null;var source=new[]{0f,.18f,.5f,1f};
  try{input.SetPixels(source.Select(x=>new Color(x,x,x,1)).ToArray());input.Apply(false,false);GL.sRGBWrite=false;Graphics.Blit(input,middle,filmic);Graphics.Blit(middle,output,encoder);RenderTexture.active=output;pixels=new Texture2D(4,1,TextureFormat.RGB24,false,true);pixels.ReadPixels(new Rect(0,0,4,1),0,0);pixels.Apply();var actual=pixels.GetPixels();var rows=new List<string>{"linearInput,filmicLinear,expectedSRGB,actualPNG_R,actualPNG_G,actualPNG_B,maxAbsError"};float worst=0;for(int i=0;i<source.Length;i++){float x=source[i],mapped=Mathf.Clamp01((x*(2.51f*x+.03f))/(x*(2.43f*x+.59f)+.14f));float expected=mapped<=.0031308f?12.92f*mapped:1.055f*Mathf.Pow(mapped,1f/2.4f)-.055f;float error=Mathf.Max(Mathf.Abs(actual[i].r-expected),Mathf.Abs(actual[i].g-expected),Mathf.Abs(actual[i].b-expected));worst=Mathf.Max(worst,error);rows.Add(string.Join(",",x,mapped,expected,actual[i].r,actual[i].g,actual[i].b,error));}File.WriteAllLines(Output+"/gpu-display-transfer-sentinel.csv",rows);File.WriteAllLines(Output+"/gpu-display-transfer-contract.txt",new[]{"Known linear HDR [0,.18,.5,1] -> existingFilmic exposure1 -> explicitIEC-sRGB -> rawRGB24readback/PNG. All render targets and upload/readback Texture2D explicitlyLinear. GL.sRGBWrite explicitlyfalse, restored. Exactlyone output transfer.","Maximumerror="+worst+" tolerance=1.01/255bytes. No actors/materialfactors/source edits; this qualifies transferonly, not sourceAgX equivalence."});File.WriteAllBytes(Output+"/gpu-display-transfer-sentinel.png",pixels.EncodeToPNG());if(worst>1.01f/255)throw new Exception("Displaytransfer sentinel RED");}
  finally{GL.sRGBWrite=oldWrite;RenderTexture.active=old;if(pixels)UnityEngine.Object.DestroyImmediate(pixels);UnityEngine.Object.DestroyImmediate(input);foreach(var r in new[]{middle,output}){r.Release();UnityEngine.Object.DestroyImmediate(r);}}
